mapper.select:
SELECT
a.bookset_id AS booksetId,
a.val_date AS valDate,
a.subject_no AS subjectNo,
a.subject_name AS subjectName,
a.cost AS cost,
a.MARKET_VALUE as marketValue
FROM BOK_VAL_TABLE_DATA a
WHERE a.bookset_id =
#{booksetId,jdbcType=VARCHAR}
AND a.val_date = #{valDate,jdbcType=DATE}
AND( a.detail_dist = #{detailDist,jdbcType=VARCHAR}
or a.detail_dist = #{otherdetailDist,jdbcType=VARCHAR}

)
AND a.SUBJECT_NO = #{subjectNo,jdbcType=VARCHAR}
AND a.LAYERING_ID IS NULL
AND a.LAYERING_ID = #{layeringId,jdbcType=VARCHAR}

select * from REP_PROD_INDEX
where VALUE_DATE=#{bookDate,jdbcType=DATE}
and PROD_ID=#{prodId,jdbcType=VARCHAR}

select * from
REP_PROD_INDEX PI
WHERE PI.VALUE_DATE=(
SELECT MAX(RX.VALUE_DATE) FROM REP_PROD_INDEX RX WHERE
RX.PROD_ID=#{prodId,jdbcType=VARCHAR}
AND RX.VALUE_DATE < #{bookDate,jdbcType=DATE}
and DECODE (
RX.NETVALUE_TDY_INCRE,NULL,RX.NETVALUE_TDY_YIELD,RX.NETVALUE_TDY_INCRE)
IS NOT NULL
) and PI.PROD_ID=#{prodId,jdbcType=VARCHAR}

SELECT SUM(TRADE_AMT) AMT FROM TRD_PRODUCT_DEAL
where 1=1
AND FINPROD_ID = #{prodId,jdbcType=VARCHAR}
and TRADE_DATE = #{valueDate,jdbcType=DATE}
and PS in ('C4','C15')

SELECT SUM(TRADE_AMT) AMT,PS FROM TRD_PRODUCT_DEAL
where 1=1
AND FINPROD_ID = #{prodId,jdbcType=VARCHAR}
and TRADE_DATE = #{valueDate,jdbcType=DATE}
and PS in ('C9','C10')
GROUP BY PS

SELECT RATE
from (
SELECT RATE,
ROWNUM AS RN
FROM REP_CASH_YIELD
WHERE busi_id = #{prodid,jdbcType=VARCHAR}
AND START_DATE <= #{valuedate,jdbcType=DATE}
AND CASH_TYPE = #{cashType,jdbcType=VARCHAR}
ORDER BY START_DATE DESC
)
WHERE RN=1

select * from BOK_ACCT_LAYERING_INFO where
BOOKSET_ID=#{booKsetId,jdbcType=VARCHAR} and
BRANCH=#{branch,jdbcType=BIGINT}
